v(1,'열둘에게 맡기신 권세','예수께서 12 제자를 불러 병을 고치고 귀신을 쫓는 권세를 맡기세요.',['예수','12 제자'],'signal look speak extend bless lower',{setting:'courtyard',effect:'light'});
d(2,'먼저 기록된 2 형제 쌍','베드로와 안드레, 야고보와 요한의 이름을 형제 관계와 함께 소개해요.','lineage',['베드로 · 안드레','야고보 · 요한','보냄받을 사도들']);
d(3,'이어지는 사도들의 이름','빌립부터 다대오까지, 서로 다른 배경의 제자들이 같은 명단에 있어요.','lineage',['빌립 · 바돌로매','도마 · 마태','알패오의 야고보 · 다대오']);
d(4,'시몬과 가룟 유다','명단의 끝에서는 시몬과, 뒤에 예수를 넘겨줄 유다가 소개돼요.','lineage',['가나나인 시몬','가룟 유다','배반의 예고']);
v(5,'첫 파송의 범위를 정하심','예수께서 이번 파송에서 갈 곳과 가지 않을 곳을 분명히 지시하세요.',['예수','12 제자'],'look speak point halt listen lower',{setting:'road'});
d(6,'먼저 찾아갈 잃은 양','이번 파송은 이스라엘 안에서 길 잃은 백성을 먼저 찾아가도록 주어져요.','map',['이스라엘','잃어버린 양','먼저 찾아감']);
v(7,'길에서 전할 소식','예수께서 제자들이 길을 가며 하나님 나라의 가까움을 전하도록 명하세요.',['예수','12 제자'],'speak signal point extend listen stand',{setting:'road'});
d(8,'거저 받은 것을 거저 나눔','치유와 회복의 사역을 대가를 얻는 수단으로 삼지 말라고 하세요.','gift',['맡기신 권세','회복의 사역','거저 나눔']);
d(9,'여행의 돈을 의지하지 않음','제자들이 파송의 길에서 돈을 미리 움켜쥐는 데 의존하지 않게 하세요.','treasure',['금 · 은 · 동전','쌓아 둘 전대','공급을 신뢰함']);
d(10,'짐보다 일꾼의 공급','과한 여행 준비를 내려놓고 사역자의 필요가 공급됨을 신뢰하게 하세요.','burden',['과한 여행 짐','보냄받은 일꾼','필요의 공급']);
d(11,'맞아 줄 집에 머묾','도착한 마을에서 합당하게 맞는 집을 찾아 떠날 때까지 머물라 하세요.','house',['들어간 마을','맞아 주는 집','머무는 사역']);
d(12,'집에 들어가 평안을 빎','방문하는 집에 들어설 때 평안의 인사를 먼저 전하라고 하세요.','door',['집에 들어감','평안의 인사','열린 만남']);
d(13,'평안을 받는 응답','평안을 비는 인사와 그 집이 보이는 응답을 구별해 설명하세요.','reconcile',['전하는 평안','맞아들이는 응답','돌아오는 평안']);
d(14,'거절당한 곳에서 떠남','말씀을 거절하는 집을 떠나며 발의 먼지를 털라는 지시를 주세요.','dust',['영접의 거절','발의 먼지를 턺','다른 곳으로']);
d(15,'거절의 책임','하나님 나라의 소식을 거절하는 일이 가볍지 않다고 심판을 경고하세요.','judgment',['거절한 마을','들은 소식','심판의 책임']);
d(16,'지혜와 순결을 함께','위험한 파송에서 속지 않는 지혜와 해치지 않는 순결을 함께 지키라 하세요.','comparison',['이리 사이의 양','뱀의 지혜','비둘기의 순결']);
d(17,'공회와 회당의 박해','제자들이 종교적 심문과 폭력을 겪을 수 있음을 미리 알리세요.','warning',['붙잡힘','공회의 심문','회당의 박해']);
d(18,'권력자 앞에서의 증언','예수 때문에 권력자 앞에 서는 자리도 복음을 증언할 기회가 돼요.','promise',['총독과 왕 앞','예수로 인한 고난','이방인에게 증언']);
d(19,'증언의 말을 주심','끌려가는 때 말의 준비만으로 모든 것을 감당하려 염려하지 말라 하세요.','promise',['심문받는 때','말의 염려','주어질 증언']);
d(20,'성령께서 돕는 증언','그 자리의 증언을 아버지의 성령께서 도우심을 약속하세요.','promise',['제자의 증언','성령의 도우심','담대히 말함']);
d(21,'가족 안의 배신까지','박해가 가족의 배신과 생명의 위협에 이를 수 있음을 숨기지 않으세요.','reconcile',['가까운 가족','배신의 고통','생명의 위협']);
d(22,'끝까지 견디는 믿음','예수의 이름 때문에 받는 미움 속에서도 끝까지 견디라고 권하세요.','promise',['이름 때문에 미움','끝까지 견딤','구원의 약속']);
d(23,'다른 마을로 피함','박해받는 곳에만 머물지 말고 다른 마을로 피하며 사역을 이어가라 하세요.','map',['박해받는 마을','피하는 길','이어지는 사명']);
d(24,'제자와 스승의 관계','제자가 스승보다 높지 않다는 관계를 통해 고난을 설명하세요.','comparison',['제자와 스승','종과 주인','따르는 관계']);
d(25,'스승이 받은 비난','예수를 비난한 이들이 제자들에게도 거친 말을 할 수 있다고 알려 주세요.','comparison',['스승에 대한 비난','제자가 겪을 일','같은 길']);
d(26,'감춰진 것이 드러남','끝내 드러날 진실을 생각하며 사람의 위협에 눌리지 말라고 하세요.','light',['감춰진 진실','드러날 때','두려움을 넘음']);
d(27,'들은 것을 밝히 전함','조용히 배운 말씀을 이제 공개적으로 전하라고 하세요.','light',['은밀히 들음','밝은 곳에서 말함','공개적인 선포']);
d(28,'참으로 경외할 분','몸을 해치는 사람보다 몸과 영혼을 다스리시는 하나님을 경외하라 하세요.','judgment',['사람의 위협','영혼까지 아시는 분','하나님 경외']);
d(29,'참새도 아시는 돌보심','값싸게 팔리는 참새도 아버지의 돌보심 밖에 있지 않다고 하세요.','bird',['작은 참새','아버지의 돌보심','잊히지 않음']);
d(30,'머리카락까지 아심','제자의 사소한 부분까지 하나님이 아심을 강조하세요.','promise',['머리카락까지','세밀한 아심','아버지의 돌보심']);
d(31,'참새보다 귀한 사람','많은 참새보다 귀한 제자들에게 두려워하지 말라고 하세요.','bird',['많은 참새','더 귀한 제자','두려워하지 않음']);
d(32,'사람 앞에서 인정함','예수를 사람들 앞에서 인정하는 응답을 아버지 앞의 인정과 연결하세요.','promise',['사람들 앞','예수를 인정함','아버지 앞의 인정']);
d(33,'부인하는 응답의 경고','사람들 앞에서 예수를 모른다고 하는 태도의 무게를 경고하세요.','judgment',['사람의 시선','예수를 부인함','책임 있는 응답']);
d(34,'복음 앞에서 생기는 갈림','예수의 오심이 일으킬 갈림을 칼에 빗대세요. 폭력을 명령하는 장면이 아니에요.','separate',['예수를 향한 응답','갈리는 선택','분열의 고통']);
d(35,'가정에서도 갈리는 응답','복음에 대한 서로 다른 응답이 가까운 가족 사이에도 갈등을 낳아요.','reconcile',['가족의 관계','서로 다른 응답','깊어지는 갈등']);
d(36,'가까운 이가 대적함','믿음 때문에 자기 집안에서도 대적을 만날 수 있음을 말씀하세요.','reconcile',['한집의 가족','대적하는 태도','믿음의 고난']);
d(37,'주님보다 앞세우지 않음','가족을 버리라는 뜻이 아니라 예수보다 높은 충성을 두지 말라는 요구예요.','heart',['소중한 가족','우선하는 충성','예수를 따름']);
d(38,'자기 십자가의 길','따르는 삶에는 자기 십자가를 지는 희생이 있음을 가르치세요.','burden',['자기 십자가','따름의 희생','주님의 길']);
d(39,'생명을 붙드는 역설','자기 보존만 붙드는 삶과 예수를 위해 내어 주는 삶을 대조하세요.','comparison',['자기 보존만','예수를 위한 내어 줌','참된 생명']);
d(40,'제자를 맞는 환대','보냄받은 이를 환대하는 일을 예수와 보내신 아버지를 맞는 일로 연결하세요.','door',['보냄받은 제자','예수를 맞이함','보내신 분']);
d(41,'믿음으로 맞는 사람','선지자와 의인을 그 정체성 때문에 환대하는 이의 상을 말씀하세요.','gift',['선지자와 의인','믿음의 환대','나누는 상']);
d(42,'작은 제자에게 준 물','보잘것없어 보이는 제자에게 준 작은 물 1그릇도 잊히지 않아요.','gift',['작은 제자','내어 준 물','잊히지 않는 섬김']);
