v(1,'다른 마을로 떠나 가르침','예수께서 파송의 지시를 마치고 여러 마을에서 가르치러 떠나세요.',['예수'],'look turn walk walk halt speak',{setting:'road',directions:{예수:'right'}});
v(2,'옥에서 제자들을 보내는 요한','갇힌 요한이 예수의 일을 듣고 제자들을 보내 확인하려 해요.',['세례 요한','요한의 제자들'],'listen look speak point signal lower',{setting:'chamber',effect:'bars'});
v(3,'오실 분이 맞는지 묻다','요한의 제자들이 예수께 기다리던 분이 맞는지 물어요.',['요한의 제자들','예수'],'walk halt bow speak listen stand',{setting:'courtyard'});
v(4,'본 것과 들은 것을 전하라','예수께서 제자들에게 직접 확인한 일을 요한에게 전하라 하세요.',['예수','요한의 제자들'],'listen speak point extend signal stand',{setting:'courtyard'});
d(5,'회복의 일들이 전하는 소식','치유와 생명의 회복, 가난한 이에게 전해진 복음이 예수의 사역을 드러내요.','gift',['몸과 생명의 회복','가난한 이에게 복음','요한에게 전할 일']);
d(6,'예수로 인해 넘어지지 않음','예수의 사역이 자기 기대와 다르다고 등을 돌리지 않는 믿음의 복을 말하세요.','promise',['자기의 기대','예수의 실제 사역','넘어지지 않는 믿음']);
v(7,'요한에 관해 묻는 예수','요한의 제자들이 떠난 뒤 예수께서 무리에게 광야에 나간 목적을 물으세요.',['예수','무리'],'look speak point listen lower stand',{setting:'desert'});
d(8,'화려함과 다른 요한의 길','화려한 옷의 왕궁과 검소한 선지자의 삶을 대조하세요.','comparison',['화려한 왕궁','검소한 요한','광야의 사역']);
d(9,'선지자보다 더한 사명','요한은 예수의 길을 직접 준비한 선구자의 역할을 맡았어요.','promise',['선지자 요한','길을 준비함','특별한 사명']);
d(10,'앞서 보냄받은 사자','요한을 앞서 길을 준비하는 사자에 관한 약속과 연결하세요.','map',['앞서 보냄','길의 준비','오시는 분']);
d(11,'요한의 큼과 새 나라의 복','요한의 큰 사명과 하나님 나라에 참여하는 복을 함께 말씀하세요.','comparison',['요한의 큰 사명','하나님 나라','작은 이의 복']);
d(12,'나라를 향한 강한 응답','역본의 표현에 차이가 있는 절이에요. 요한 때부터 드러난 나라의 역동성과 응답을 살펴봐요.','comparison',['요한 때부터','나라의 역동성','간절한 응답']);
d(13,'요한까지 이어진 예언','율법과 선지자의 예언이 요한의 사역에 이르기까지 이어졌음을 말씀하세요.','lineage',['율법과 선지자','요한의 사역','예언의 전환점']);
d(14,'엘리야의 사명을 잇는 요한','요한이 엘리야의 사명을 잇는 선구자라는 뜻이지 육체의 환생을 뜻하지 않아요.','promise',['엘리야의 사명','길을 준비하는 요한','받아들일 응답']);
v(15,'진지하게 들으라는 촉구','예수께서 지금 들은 말씀을 마음에 새겨 들으라고 촉구하세요.',['예수','무리'],'look signal speak point listen lower',{setting:'courtyard'});
d(16,'장터의 아이들에 빗댐','예수께서 응답하지 않는 세대를 장터의 놀이에 빗대기 시작하세요.','comparison',['장터의 아이들','함께하자는 부름','응답하지 않는 이들']);
d(17,'기쁨에도 슬픔에도 무반응','기쁜 놀이에도 슬픈 놀이에도 응하지 않는 태도로 완고함을 드러내세요.','comparison',['피리의 기쁨','애곡의 슬픔','어느 쪽에도 무반응']);
d(18,'요한의 절제를 비난함','사람들은 요한의 절제된 삶마저 귀신의 일이라고 비난했어요.','comparison',['요한의 절제','왜곡하는 비난','거절하는 태도']);
d(19,'예수의 식탁도 비난함','함께 먹는 예수도 비난하면서 참된 지혜의 열매는 보지 않는 태도를 지적하세요.','comparison',['죄인과의 식탁','다른 이유의 비난','행동으로 드러난 지혜']);
v(20,'회개하지 않는 고을을 책망함','예수께서 많은 권능을 보고도 돌아서지 않은 고을들을 책망하세요.',['예수','무리'],'look speak point halt lower stand',{setting:'courtyard',emotion:'determined'});
d(21,'고라신과 벳새다의 책임','많이 받은 은혜에 응답하지 않는 고을을 다른 도시들과 대조하세요.','judgment',['고라신 · 벳새다','행하신 권능','돌이키지 않음']);
d(22,'더 무거운 심판의 경고','두로와 시돈보다 무거운 책임을 지게 될 것을 경고하세요.','judgment',['들은 고을','두로 · 시돈과 비교','더 큰 책임']);
d(23,'가버나움의 자만을 꺾음','권능을 본 가버나움이 스스로 높아지려 하면서 회개하지 않는 태도를 책망하세요.','judgment',['높아지려는 가버나움','많이 본 권능','낮아질 경고']);
d(24,'소돔과 대조되는 책임','가버나움이 받은 계시를 거절한 책임의 무게를 소돔과 대조하세요.','judgment',['소돔과의 대조','더 많이 받은 계시','응답의 책임']);
v(25,'아버지께 감사하시는 예수','예수께서 스스로 지혜롭다는 이보다 작은 이에게 드러내신 아버지께 감사하세요.',['예수'],'look lift pray bless lower bow',{setting:'courtyard'});
v(26,'아버지의 뜻을 기뻐함','예수께서 아버지의 기뻐하시는 뜻에 동의하며 감사의 기도를 이으세요.',['예수'],'listen look lift pray lower bow',{setting:'courtyard'});
d(27,'아들이 드러내시는 아버지','아버지와 아들의 특별한 관계와 아들을 통한 계시를 말씀하세요.','promise',['아버지와 아들','아들의 계시','아버지를 앎']);
d(28,'지친 이들을 쉼으로 초대함','수고와 짐에 눌린 이들을 예수께서 자기에게 와서 쉬도록 초대하세요.','burden',['수고와 무거운 짐','예수께 나아감','주시는 쉼']);
d(29,'온유한 주님께 배움','겸손하고 온유한 예수께 배우며 그 멍에 안에서 쉼을 얻도록 하세요.','burden',['온유하고 겸손하심','주님의 멍에','배우며 얻는 쉼']);
d(30,'주님이 주시는 가벼운 짐','예수께서 맡기시는 멍에와 짐의 선함을 말씀하세요.','burden',['주님의 멍에','주시는 짐','배움의 안식']);
