v(1,'배고파 이삭을 먹는 제자들','안식일에 밀밭을 지나는 제자들이 허기를 달래려고 이삭을 따 먹어요.',['제자들','예수'],'walk bend grasp lift eat lower',{setting:'pasture',prop:'grain'});
v(2,'안식일을 문제 삼는 바리새인','바리새인들이 이삭을 먹는 행동을 보고 예수께 고발하듯 말해요.',['바리새인','예수'],'look point speak halt listen lower',{setting:'pasture'});
d(3,'굶주렸던 다윗의 예','예수께서 다윗과 동료들이 굶주렸을 때의 일을 기억하게 하세요.','promise',['다윗과 동료들','굶주린 상황','다시 읽을 말씀']);
d(4,'진설병을 먹은 사건','굶주린 다윗에게 주어졌던 진설병의 사례로 필요와 자비를 설명하세요.','gift',['제사장의 진설병','굶주린 다윗','필요와 자비']);
d(5,'안식일에도 섬기는 제사장','안식일 성전 사역을 근거로 단순한 금지의 잣대를 돌아보게 하세요.','comparison',['안식일','성전의 제사장','죄 없이 섬김']);
d(6,'성전보다 크신 분','예수께서 성전보다 큰 권위를 가진 분이 여기 계심을 밝히세요.','promise',['성전','더 크신 예수','주님의 권위']);
d(7,'정죄보다 자비를 배움','자비를 원하시는 뜻을 알았다면 죄 없는 이들을 정죄하지 않았을 것이라 하세요.','reconcile',['자비를 바라심','무죄한 제자들','멈춰야 할 정죄']);
v(8,'안식일의 주인이신 예수','예수께서 인자가 안식일의 주인임을 선언하세요.',['예수','바리새인'],'look speak extend point listen stand',{setting:'pasture'});
v(9,'회당에 들어가심','예수께서 그곳을 떠나 회당 안으로 들어가세요.',['예수'],'turn walk walk halt look stand',{setting:'chamber'});
v(10,'손 마른 사람을 두고 하는 질문','사람들은 손 마른 이를 앞에 두고 예수를 고발할 근거를 찾으며 질문해요.',['바리새인','예수','손 마른 사람'],'look point speak listen lower stand',{setting:'chamber'});
d(11,'구덩이의 양을 건지는 예','안식일이라도 빠진 양을 구할 것이라는 예로 자비의 행동을 묻게 하세요.','gift',['구덩이에 빠진 양','건져 주는 행동','안식일의 자비']);
d(12,'사람을 위한 선한 일','사람이 양보다 귀하므로 안식일에 선을 행하는 것이 옳다고 하세요.','comparison',['귀한 사람','안식일의 목적','행해야 할 선']);
v(13,'손을 펴자 회복됨','예수의 말씀에 손 마른 사람이 손을 내밀자 온전해져요.',['예수','손 마른 사람'],'look speak signal lower look stand',{setting:'chamber',placements:{예수:{x:300,y:235},'손 마른 사람':{x:390,y:235}},tracks:{'손 마른 사람':['lower','look','reach','extend','inspect','stand']},effect:'heal'});
