v(15,'떠나시며 따르는 이들을 고침','예수께서 위협을 아시고 떠나시지만 따라온 병든 이들을 계속 고치세요.',['예수','무리'],'look turn walk halt reach touch',{setting:'road',effect:'heal',tracks:{무리:['walk','walk','halt','sit','rise','stand']}});
v(16,'드러내지 말라는 당부','예수께서 자신을 함부로 드러내지 말라고 엄히 이르세요.',['예수','무리'],'look speak halt point listen lower',{setting:'road'});
d(17,'종의 예언과 사역의 연결','이사야가 전한 종의 약속이 예수의 사역에서 이루어짐을 밝히세요.','promise',['이사야의 예언','종의 사역','예수 안의 성취']);
d(18,'기뻐하시는 종의 사명','택하신 종이 성령으로 정의를 이방에 전할 것을 예언의 말로 소개해요.','promise',['기뻐하시는 종','성령의 사역','이방에 전할 정의']);
d(19,'다투어 과시하지 않는 종','소란과 다툼으로 자신을 과시하지 않는 종의 길을 그려요.','comparison',['소란과 다툼','조용한 사역','종의 온유함']);
d(20,'연약한 것을 지키는 종','상한 갈대와 꺼져 가는 불꽃을 해치지 않는 모습으로 온유한 돌봄을 보여 줘요.','reed-lamp',['상한 갈대','꺼져 가는 심지','끝까지 지키심']);
d(21,'이방도 바라볼 이름','예수의 이름에 이방 사람들도 소망을 두게 될 것을 전해요.','promise',['이방의 사람들','그 이름을 바람','주어질 소망']);
v(22,'보고 말하게 된 사람','예수께서 귀신 들려 보지도 말하지도 못하던 이를 고치세요.',['예수','귀신 들린 자'],'look listen speak extend lower stand',{setting:'courtyard',effect:'heal',tracks:{'귀신 들린 자':['lower','look','startle','speak','look','stand']}});
v(23,'메시아가 아닐까 놀라는 무리','무리가 일어난 치유를 보고 다윗의 자손이 아닐까 놀라 물어요.',['무리'],'look startle turn speak look stand',{setting:'courtyard',emotion:'surprised'});
v(24,'성령의 일을 왜곡하는 비난','바리새인들이 예수의 축귀를 귀신의 우두머리의 일로 돌리며 비난해요.',['바리새인'],'look point speak turn listen lower',{setting:'courtyard'});
d(25,'스스로 갈라지면 무너짐','예수께서 나라와 집이 자기 안에서 싸우면 설 수 없다는 예로 답하세요.','house-fall',['내부의 다툼','갈라진 집','무너지는 결과']);
d(26,'사탄의 자멸이라는 모순','사탄이 스스로 사탄을 쫓아낸다는 비난의 모순을 드러내세요.','comparison',['사탄의 나라','스스로 쫓아냄','설 수 없는 모순']);
d(27,'그들 자신의 축귀와 비교함','예수만 악한 힘으로 일한다고 비난하는 기준을 그들의 사역에도 비추세요.','balance',['예수를 향한 비난','그들의 축귀','같은 기준의 질문']);
