v(22,'사람의 손에 넘겨질 예고','예수께서 갈릴리에서 인자가 사람들의 손에 넘겨질 것을 말씀하세요.',['예수','제자들'],'look speak extend lower listen stand',{setting:'courtyard'});
v(23,'죽음과 부활을 듣고 근심함','제자들은 죽음과 부활의 예고를 듣고 크게 근심해요.',['제자들','예수'],'listen startle lower sit look stand',{setting:'courtyard',emotion:'sad'});
v(24,'성전세를 묻는 사람들','성전세를 걷는 사람들이 베드로에게 예수의 납부 여부를 물어요.',['성전세 걷는 사람들','베드로'],'walk halt speak extend listen lower',{setting:'courtyard'});
v(25,'베드로에게 되묻는 예수','집에 들어온 베드로에게 예수께서 왕이 누구에게 세금을 받는지 물으세요.',['예수','베드로'],'look speak point listen lower stand',{setting:'chamber'});
v(26,'아들의 자유에 관한 응답','베드로의 대답을 들은 예수께서 아들의 자유를 설명하세요.',['예수','베드로'],'listen look speak extend lower stand',{setting:'chamber'});
d(27,'물고기의 돈으로 낼 성전세','예수께서 낚시로 얻을 돈으로 2 사람의 성전세를 내도록 지시하세요.','fish-coin',['낚시의 지시','물고기 입의 돈','2 사람의 성전세']);
additionalPeople[17]=[{name:'제자들',role:'예수와 함께 산에서 내려오고 가르침을 듣던 이들',refs:['마태복음 17:6','마태복음 17:19']},{name:'성전세 걷는 사람들',role:'베드로에게 반 세겔 납부를 물은 이들',refs:['마태복음 17:24']}];
chapter=18;
v(1,'큰 사람을 묻는 제자들','제자들이 예수께 하나님 나라에서 누가 큰 사람인지 물어요.',['제자들','예수'],'walk halt speak point listen stand',{setting:'courtyard'});
v(2,'아이를 가운데 세우심','예수께서 아이 하나를 불러 제자들 가운데 세우세요.',['예수','어린아이','제자들'],'signal look extend point lower stand',{setting:'courtyard',tracks:{어린아이:['look','walk','walk','halt','stand','stand']},portrayals:{어린아이:{scale:.65,hideBeard:true}}});
d(3,'돌이켜 아이처럼 됨','예수께서 어린아이처럼 자신을 낮추는 돌이킴이 필요하다고 하세요.','heart',['크기를 겨룸','돌이키는 마음','어린아이 같은 겸손']);
d(4,'자기를 낮추는 큰 사람','나라에서 큰 이는 어린아이처럼 자기를 낮추는 사람이라고 하세요.','comparison',['자기를 높임','아이 같은 낮아짐','나라의 크기']);
d(5,'작은 아이를 맞는 환대','예수의 이름으로 아이를 맞는 일이 예수를 맞는 일이라고 하세요.','door',['작은 아이','예수의 이름으로 환대','예수를 맞이함']);
d(6,'작은 이를 넘어뜨리지 말라','믿는 작은 이를 죄에 빠뜨리는 책임이 얼마나 무거운지 경고하세요.','judgment',['작은 이의 믿음','넘어뜨리는 행동','무거운 책임']);
d(7,'걸림을 만드는 자의 책임','세상에 걸림이 있어도 그것을 만드는 사람의 책임은 사라지지 않아요.','warning',['세상의 걸림','내가 만든 걸림','피할 수 없는 책임']);
d(8,'죄의 통로를 끊는 결단','손과 발을 버린다는 강한 비유로 죄와 타협하지 말라고 하세요.','warning',['죄로 이끄는 행동','단호히 끊는 결단','생명의 가치']);
d(9,'보는 욕망도 돌아봄','눈을 버린다는 비유로 죄의 유혹을 생명보다 앞세우지 말라고 하세요.','warning',['죄로 이끄는 눈','끊어야 할 유혹','더 귀한 생명']);
d(10,'작은 이를 업신여기지 말라','아버지 앞에서 귀하게 여겨지는 작은 이를 멸시하지 말라고 하세요.','promise',['작은 1 사람','하나님 앞의 존귀함','업신여기지 않음']);
d(11,'이 번호의 본문 표기','업로드한 2 역본 모두 이 절을 본문 없음으로 표시해요. 별도의 사건 동작을 덧붙이지 않아요.','edition-note',['18장 11절','2 역본의 본문 없음','본문 표기 안내'],{textualNotice:true});
d(12,'잃은 1마리를 찾음','목자가 무리를 두고 길 잃은 한 양을 찾아가는 비유를 들어요.','lost-sheep',['100마리 중 하나','찾으러 나서는 목자','길 잃은 양']);
d(13,'찾은 양으로 인한 기쁨','잃었던 양을 찾았을 때의 큰 기쁨을 말씀하세요.','lost-sheep',['찾아 나선 길','되찾은 한 양','발견의 기쁨']);
d(14,'하나도 잃지 않으려는 뜻','작은 1 사람도 잃지 않는 것이 아버지의 뜻이라고 하세요.','promise',['작은 1 사람','잃기를 원치 않으심','아버지의 뜻']);
d(15,'먼저 둘이서 권고함','형제의 잘못을 먼저 단둘이 권고하여 관계를 회복하도록 하세요.','reconcile',['형제의 잘못','단둘이 권고','듣고 회복함']);
d(16,'증인과 함께 다시 권함','듣지 않으면 한두 사람과 함께 다시 사실을 확인하며 권하라고 하세요.','reconcile',['들으려 하지 않음','한두 증인과 함께','사실을 분명히 함']);
d(17,'공동체의 권고까지','끝까지 듣지 않는 경우 교회의 권고와 경계가 필요함을 가르치세요.','door',['함께 권고함','교회에도 듣지 않음','공동체의 경계']);
d(18,'매고 푸는 공동체의 책임','공동체가 매고 푸는 판단을 하늘의 뜻 앞에서 신중히 맡아야 해요.','promise',['땅에서의 판단','매고 푸는 책임','하늘의 뜻 앞에서']);
d(19,'마음을 같이한 간구','공동체가 마음을 같이하여 구하는 기도에 아버지의 응답을 약속하세요.','reconcile',['마음을 같이함','함께 드리는 간구','아버지의 응답']);
d(20,'이름으로 모인 곳에 함께하심','예수의 이름으로 모인 작은 공동체 가운데 함께하심을 약속하세요.','promise',['두세 사람의 모임','예수의 이름','함께하시는 주님']);
v(21,'용서의 횟수를 묻는 베드로','베드로가 형제의 잘못을 어디까지 용서해야 하는지 물어요.',['베드로','예수'],'walk halt speak count listen stand',{setting:'courtyard'});
d(22,'계산으로 제한하지 않는 용서','예수께서는 횟수 계산으로 용서의 한계를 정하지 말라고 하세요.','reconcile',['일곱 번이라는 질문','제한하지 않는 용서','형제를 향한 마음']);
const pv=(n,t,s,actors,actions,extra={})=>v(n,t,s,actors,actions,{...extra,mode:'parable'});
pv(23,'결산을 시작하는 왕의 비유','예수께서 종들과 셈을 하려는 왕의 비유로 나라를 설명하세요.',['왕'],'sit open read count look stand',{setting:'court',prop:'scroll'});
pv(24,'갚을 수 없는 빚의 종','엄청난 빚을 진 종이 왕 앞에 불려 와요.',['왕','무자비한 종'],'read count inspect point listen stand',{setting:'court',prop:'scroll',tracks:{'무자비한 종':['walk','halt','look','lower','kneel','kneel']}});
pv(25,'갚지 못한 종에게 내려진 명령','갚을 길이 없는 종에게 가족과 소유까지 팔아 갚으라는 명령이 내려져요.',['왕','무자비한 종'],'read look speak point signal stand',{setting:'court',tracks:{'무자비한 종':['kneel','lower','look','bow','kneel','kneel']}});
pv(26,'기다려 달라고 엎드려 빎','종이 왕 앞에 엎드려 더 기다려 달라고 간청해요.',['무자비한 종','왕'],'kneel bow speak extend bow kneel',{setting:'court',emotion:'worried'});
pv(27,'불쌍히 여겨 빚을 없애 줌','왕은 종을 불쌍히 여겨 놓아 보내고 빚을 탕감해요.',['왕','무자비한 종'],'look listen extend release bless lower',{setting:'court',emotion:'gentle',tracks:{'무자비한 종':['kneel','look','rise','bow','turn','walk']}});
pv(28,'동료를 붙들고 갚으라 함','큰 빚을 탕감받은 종이 작은 빚을 진 동료를 붙들고 거칠게 갚으라고 해요.',['무자비한 종','동료 종'],'walk reach hold hold speak lower',{setting:'courtyard',placements:{'무자비한 종':{x:330,y:235},'동료 종':{x:390,y:235}},tracks:{'동료 종':['stand','startle','brace','brace','kneel','kneel']}});
pv(29,'동료도 기다려 달라고 빎','동료 종도 앞서 그가 했던 것처럼 엎드려 기다려 달라고 빌어요.',['동료 종','무자비한 종'],'kneel bow speak extend bow kneel',{setting:'courtyard',emotion:'worried'});
pv(30,'부탁을 거절당하고 갇힌 동료','동료의 간청은 거절되고 빚을 갚을 때까지 감옥에 갇혀요.',['동료 종','무자비한 종'],'look lower walk halt sit lower',{setting:'chamber',effect:'bars',emotion:'sad'});
pv(31,'일어난 일을 왕에게 알림','다른 동료들이 이 일을 안타깝게 여겨 왕에게 모두 전해요.',['다른 동료들','왕'],'walk halt bow speak point lower',{setting:'court',emotion:'sad'});
pv(32,'탕감한 일을 상기시키는 왕','왕이 종을 불러 그가 빌었기에 모든 빚을 없애 주었다고 꾸짖어요.',['왕','무자비한 종'],'signal look speak point halt lower',{setting:'court',emotion:'angry'});
pv(33,'받은 자비를 나눠야 했음','왕이 자신에게 받은 자비를 동료에게도 베풀어야 하지 않았느냐고 물어요.',['왕','무자비한 종'],'look speak extend point listen stand',{setting:'court',emotion:'determined'});
pv(34,'무자비한 종이 받는 판단','종은 자기가 동료에게 했던 것처럼 감옥에 넘겨져 책임을 져요.',['무자비한 종','왕'],'listen startle lower walk sit lower',{setting:'chamber',effect:'bars',emotion:'worried'});
d(35,'마음으로부터 용서하라','예수께서 비유를 맺으며 형제를 마음으로 용서해야 한다고 경고하세요.','heart',['받은 용서','형제를 향한 마음','진실한 용서의 요청']);
additionalPeople[18]=[{name:'다른 동료들',role:'무자비한 종의 일을 왕에게 알린 비유 속 종들',refs:['마태복음 18:31']}];
chapter=19;
v(1,'요단 건너 유대로 가심','예수께서 말씀을 마치고 갈릴리를 떠나 요단 건너 유대 지경으로 가세요.',['예수'],'look turn walk walk halt stand',{setting:'road',directions:{예수:'right'}});
v(2,'따라온 무리를 고치심','많은 사람이 뒤따라오자 예수께서 병든 이들을 고치세요.',['예수','무리'],'look listen reach touch lower inspect',{setting:'road',effect:'heal',tracks:{무리:['walk','halt','sit','sit','rise','stand']}});
v(3,'이혼으로 시험하는 질문','바리새인들이 어떤 이유로든 아내를 버려도 되는지 예수를 시험해 물어요.',['바리새인','예수'],'walk halt speak point listen lower',{setting:'courtyard'});
d(4,'창조의 뜻을 돌아보심','예수께서 사람을 남자와 여자로 지으신 창조의 뜻을 상기시키세요.','promise',['처음 지으신 분','남자와 여자','창조의 뜻']);
d(5,'떠나 연합하는 혼인','부모를 떠나 배우자와 연합해 한 몸이 된다는 말씀을 읽게 하세요.','reconcile',['부모를 떠남','배우자와 연합','한 몸이 됨']);
d(6,'하나님이 맺어 주신 관계','하나님께서 맺어 주신 혼인을 사람이 가볍게 갈라놓지 말라고 하세요.','reconcile',['둘에서 한 몸으로','하나님이 맺으심','가볍게 나누지 않음']);
v(7,'모세의 허용을 되묻는 이들','바리새인들이 이혼 증서를 주는 모세의 규정을 다시 물어요.',['바리새인','예수'],'listen speak open point listen lower',{setting:'courtyard',prop:'scroll'});
d(8,'완악함 때문에 주어진 허용','예수께서 이혼의 허용은 사람의 완악함 때문이지 처음의 뜻이 아니라고 하세요.','comparison',['처음의 뜻','사람의 완악함','허용된 규정']);
d(9,'배우자를 버리는 죄','혼인의 신실함을 깨뜨리는 이혼과 재혼의 책임을 엄중히 말씀하세요.','warning',['혼인의 신실함','쉽게 버리는 관계','뒤따르는 죄의 책임']);
v(10,'혼인하지 않는 편이 낫냐는 반응','제자들은 엄중한 말씀을 듣고 혼인하지 않는 편이 낫지 않겠느냐고 말해요.',['제자들','예수'],'listen startle speak extend listen lower',{setting:'courtyard'});
d(11,'각 사람에게 허락되는 부르심','혼인하지 않는 삶도 모든 사람이 똑같이 감당하는 부르심은 아니라고 하세요.','promise',['모든 사람의 동일한 길 아님','허락된 부르심','받는 사람의 응답']);
d(12,'혼인하지 않는 여러 사정','태생과 사람의 사정, 나라를 위한 선택을 구별하며 감당할 부르심을 말씀하세요.','comparison',['여러 삶의 사정','나라를 위한 선택','받을 수 있는 부르심']);
v(13,'아이들을 데려오자 막는 제자들','사람들이 축복을 바라며 아이들을 데려오지만 제자들은 막아요.',['어린아이들','제자들','예수'],'walk halt look wait listen stand',{setting:'courtyard',tracks:{제자들:['look','halt','point','speak','listen','stand']},portrayals:{어린아이들:{scale:.65,hideBeard:true,copies:2}}});
v(14,'아이들의 길을 여시는 예수','예수께서 아이들이 자신에게 오는 것을 막지 말라고 하세요.',['예수','어린아이들','제자들'],'look halt speak extend signal stand',{setting:'courtyard',portrayals:{어린아이들:{scale:.65,hideBeard:true,copies:2}}});
v(15,'아이들에게 손을 얹으심','예수께서 아이들에게 손을 얹어 기도하신 뒤 떠나세요.',['예수','어린아이들'],'look reach touch bless lower walk',{setting:'courtyard',placements:{예수:{x:300,y:235},어린아이들:{x:390,y:235}},portrayals:{어린아이들:{scale:.65,hideBeard:true,copies:2}}});
v(16,'영생을 묻는 청년','한 청년이 예수께 와서 영생을 얻으려면 어떤 선을 해야 하는지 물어요.',['부자 청년','예수'],'walk halt bow speak listen stand',{setting:'road'});
v(17,'선하신 분과 계명을 말씀하심','예수께서 선하신 분을 바라보며 계명의 뜻을 따르라고 응답하세요.',['예수','부자 청년'],'listen speak point extend listen lower',{setting:'road'});
