d(21,'가이사와 하나님께 돌릴 것','예수께서 세금의 질문을 하나님께 속한 것을 돌리는 책임까지 넓혀 답하세요.','balance',['가이사에게 속한 것','하나님께 속한 것','돌려드릴 책임']);
v(22,'놀라서 물러가는 이들','질문하던 이들이 대답을 듣고 놀라 예수를 떠나요.',['헤롯 당원','바리새인의 제자들'],'listen startle lower turn walk stand',{setting:'road',directions:{'헤롯 당원':'right','바리새인의 제자들':'right'}});
v(23,'부활을 부정하는 이들의 질문','사두개인들이 예수께 와서 부활을 문제 삼는 질문을 시작해요.',['사두개인','예수'],'walk halt speak point listen lower',{setting:'courtyard'});
d(24,'계대 혼인의 규정을 끌어옴','그들은 상속자를 세우는 모세의 규정을 질문의 근거로 들어요.','promise',['상속자를 잃은 집','모세의 규정','이어질 가정의 질문']);
d(25,'일곱 형제라는 가정','자녀 없이 죽은 형과 남은 배우자라는 가정으로 논쟁을 꾸려요.','lineage',['일곱 형제라는 가정','자녀 없이 죽은 형','다음 혼인']);
d(26,'이어지는 형제들의 죽음','그들의 가정에서는 다른 형제들도 같은 일을 겪게 돼요.','lineage',['둘째와 셋째','같이 되풀이된 일','일곱째까지의 가정']);
d(27,'배우자의 죽음까지','그들은 끝에 그 여자도 죽었다는 조건을 덧붙여요.','lament',['이어진 죽음의 가정','마지막 배우자','논쟁의 조건']);
d(28,'누구의 아내인지 묻는 논리','지상의 혼인 관계를 그대로 연장해 부활을 모순으로 만들려 해요.','comparison',['지상의 혼인 관계','부활 때의 질문','한정된 가정의 논리']);
v(29,'성경과 능력을 모르기 때문','예수께서 성경과 하나님의 능력을 모르는 오해라고 답하세요.',['예수','사두개인'],'look speak open point listen stand',{setting:'courtyard',prop:'scroll'});
d(30,'현재와 다른 부활의 삶','부활의 삶을 현세의 혼인 구조와 똑같이 가정할 수 없음을 가르치세요.','comparison',['현재의 혼인','부활의 새 삶','천사처럼 혼인하지 않음']);
v(31,'부활에 관한 말씀을 읽으라','예수께서 하나님이 하신 말씀을 성경에서 다시 읽게 하세요.',['예수','사두개인'],'open read show point listen lower',{setting:'courtyard',prop:'scroll'});
d(32,'살아 있는 이들의 하나님','아브라함과 이삭과 야곱의 하나님이시라는 말씀으로 생명의 소망을 밝히세요.','promise',['언약의 조상들','변치 않는 하나님','살아 있는 이들의 하나님']);
v(33,'가르침에 놀라는 무리','사람들은 예수의 성경 풀이를 듣고 놀라요.',['무리'],'listen look startle speak look stand',{setting:'courtyard',emotion:'surprised'});
v(34,'다시 모인 바리새인들','사두개인들이 대답하지 못했다는 말을 듣고 바리새인들이 모여요.',['바리새인'],'listen look walk halt speak stand',{setting:'courtyard'});
v(35,'율법사의 시험','그들 가운데 한 율법사가 예수를 시험하려고 질문을 꺼내요.',['율법사','예수'],'walk halt speak point listen stand',{setting:'courtyard'});
v(36,'어느 계명이 큰지 물음','율법사가 율법에서 가장 큰 계명이 무엇인지 물어요.',['율법사','예수'],'look speak extend listen lower stand',{setting:'courtyard'});
d(37,'전 존재로 하나님을 사랑함','예수께서 마음과 생명과 뜻을 다하여 하나님을 사랑하라고 답하세요.','heart',['마음과 생명과 뜻','하나님을 사랑함','전 존재의 응답']);
d(38,'크고 첫째인 계명','하나님 사랑이 크고 우선되는 계명임을 밝히세요.','promise',['하나님 사랑','가장 큰 계명','먼저 둘 응답']);
d(39,'자신처럼 이웃을 사랑함','이웃을 자신처럼 사랑하라는 계명도 그와 함께 중요하다고 하세요.','reconcile',['자신을 아끼듯','이웃을 사랑함','함께 붙드는 계명']);
d(40,'말씀을 지탱하는 두 사랑','율법과 선지자의 모든 가르침이 하나님 사랑과 이웃 사랑에 걸려 있다고 하세요.','promise',['하나님 사랑','이웃 사랑','온 말씀의 뜻']);
v(41,'예수께서 물으시는 차례','모인 바리새인들에게 예수께서 질문을 시작하세요.',['예수','바리새인'],'look speak point wait listen stand',{setting:'courtyard'});
v(42,'그리스도가 누구의 자손인지 물음','예수께서 묻자 그들은 다윗의 자손이라고 답해요.',['예수','바리새인'],'look speak listen point lower stand',{setting:'courtyard'});
d(43,'다윗이 부른 주','예수께서 다윗이 성령 안에서 그리스도를 주라고 부른 사실을 물으세요.','promise',['다윗의 증언','성령의 감동','그리스도를 주라 부름']);
d(44,'오른편에 앉으시는 주','예수께서 시편의 말씀으로 그리스도의 높으신 권위를 드러내세요.','promise',['주의 말씀','오른편의 자리','원수를 이기는 권위']);
d(45,'자손이면서 다윗의 주','그리스도를 혈통의 계보만으로 다 설명할 수 없음을 밝히세요.','comparison',['다윗의 자손','다윗이 부른 주','더 크신 그리스도']);
v(46,'말문이 막힌 사람들','그들은 더 대답하지 못하고 그날 이후 함부로 예수를 시험하지 못해요.',['바리새인','예수'],'listen startle lower look turn stand',{setting:'courtyard'});
additionalPeople[22]=[{name:'잔치의 종들',role:'사람들을 초청한 비유 속 종들',refs:['마태복음 22:3']},{name:'청함받은 사람들',role:'잔치를 거절한 비유 속 초청객들',refs:['마태복음 22:3','마태복음 22:5']},{name:'잔치의 손님들',role:'길에서 초청되어 잔치에 온 비유 속 사람들',refs:['마태복음 22:10']},{name:'예복 없는 손님',role:'왕의 물음에 답하지 못한 비유 속 손님',refs:['마태복음 22:11']},{name:'바리새인의 제자들',role:'헤롯 당원들과 함께 질문하러 온 사람들',refs:['마태복음 22:16']},{name:'무리',role:'부활에 관한 가르침에 놀란 사람들',refs:['마태복음 22:33']}];
chapter=23;
v(1,'무리와 제자들에게 말씀하심','예수께서 무리와 제자들에게 지도자들의 위선에 관해 말씀하세요.',['예수','무리','제자들'],'look speak point listen extend stand',{setting:'courtyard'});
d(2,'모세의 자리에 앉은 이들','서기관과 바리새인들이 율법을 가르치는 권위의 자리를 맡았음을 말하세요.','promise',['모세의 자리','율법을 가르침','맡겨진 책임']);
d(3,'말은 지키되 행동은 따르지 말라','말씀을 가르치면서 행하지 않는 이들의 행동을 본받지 말라고 하세요.','comparison',['말씀의 가르침','행하지 않는 지도자','말과 행동의 구별']);
d(4,'남에게만 지운 무거운 짐','다른 이에게 무거운 의무를 지우면서 돕지 않는 위선을 지적하세요.','burden',['남의 어깨에 올린 짐','돕지 않는 지도자','함께 져야 할 책임']);
d(5,'보이기 위해 꾸미는 경건','옷과 경문을 크게 꾸며 사람에게 경건해 보이려는 태도를 드러내세요.','comparison',['겉의 경문과 옷술','사람의 시선을 구함','과시하는 경건']);
d(6,'높은 자리를 좋아함','잔치와 회당에서 앞자리를 찾는 마음을 지적하세요.','comparison',['잔치의 윗자리','회당의 높은 자리','높아지려는 마음']);
d(7,'호칭과 인사를 탐냄','사람들의 인사와 존경받는 호칭을 좋아하는 태도를 드러내세요.','heart',['장터의 인사','높여 부르는 호칭','인정을 탐내는 마음']);
d(8,'한 선생 앞의 형제들','제자들은 스스로 높아지는 호칭보다 한 선생 앞에서 형제임을 기억해야 해요.','reconcile',['한 분인 선생','서로를 높이지 않음','함께 선 형제들']);
d(9,'궁극의 아버지를 기억함','하늘의 아버지 자리에 사람을 올려놓지 말라고 가르치세요.','promise',['궁극의 아버지','하늘에 계신 한 분','사람을 절대화하지 않음']);
d(10,'그리스도가 주시는 인도','궁극의 지도자는 그리스도 한 분임을 기억하게 하세요.','promise',['높은 호칭을 찾음','한 분인 그리스도','그분의 인도를 따름']);
d(11,'큰 사람의 섬김','공동체에서 큰 사람은 다른 이를 섬기는 사람이 되어야 해요.','gift',['크고자 하는 사람','이웃의 필요','섬기는 삶']);
d(12,'높아짐과 낮아짐의 역전','자기를 높이는 삶과 낮추는 삶의 끝이 뒤바뀜을 말씀하세요.','comparison',['자기를 높임','자기를 낮춤','뒤바뀌는 평가']);
d(13,'나라의 문을 막는 위선','자신도 들어가지 않으면서 다른 사람의 길까지 막는 지도자들을 책망하세요.','door',['들어가지 않는 지도자','가로막힌 문','막힌 사람들의 길']);
d(14,'이 번호의 본문 표기','업로드한 2 역본 모두 이 번호를 본문 없음으로 표시해요. 별도 사건을 만들어 넣지 않아요.','edition-note',['23장 14절','2 역본의 본문 없음','본문 표기 안내'],{textualNotice:true});
d(15,'잘못 이끄는 열심','멀리 다니며 사람을 얻어도 더 나쁜 길로 이끈다면 그 열심은 선하지 않아요.','map',['사람을 얻는 열심','잘못된 가르침','더 나빠진 결과']);
d(16,'금에 매인 맹세의 잣대','성전보다 금을 높이는 비뚤어진 맹세의 기준을 지적하세요.','balance',['성전으로 한 맹세','금으로 한 맹세','뒤집힌 가치 기준']);
d(17,'금을 거룩하게 하는 성전','금을 높이면서 그 금이 거룩해지는 뜻을 놓친 모순을 물으세요.','comparison',['성전의 금','거룩하게 하는 성전','더 중요한 근원']);
d(18,'예물만 무겁게 보는 기준','제단보다 예물에만 무게를 두는 자의적인 맹세를 지적하세요.','balance',['제단','그 위의 예물','자의적인 맹세']);
d(19,'예물을 거룩하게 하는 제단','예물의 가치를 그 근원인 제단과 갈라놓지 말라고 하세요.','comparison',['드려진 예물','거룩하게 하는 제단','뒤바뀐 중요성']);
d(20,'제단과 그 위의 모든 것','제단을 두고 한 맹세를 그 위의 것들과 분리할 수 없다고 설명하세요.','promise',['제단의 맹세','그 위의 모든 것','나누지 못할 책임']);
d(21,'성전과 그 안에 계신 분','성전의 맹세가 그곳에 계신 하나님 앞의 말임을 드러내세요.','promise',['성전을 두고 한 말','그 안에 계신 하나님','하나님 앞의 책임']);
d(22,'하늘도 내 담보가 아님','하늘을 두고 한 맹세도 보좌에 계신 하나님 앞의 책임이라고 하세요.','promise',['하늘을 두고 한 맹세','하나님의 보좌','가볍게 못할 말']);
d(23,'작은 규정과 더 큰 정의','작은 십일조를 지키면서 정의와 긍휼과 신실함을 버린 위선을 책망하세요.','balance',['작은 십일조','정의 · 긍휼 · 믿음','함께 지켜야 할 뜻']);
d(24,'작은 것을 걸러 큰 것을 삼킴','작은 흠에만 매여 더 큰 잘못을 놓치는 우스꽝스러운 역전을 비유하세요.','gnat-camel',['작은 흠만 걸러냄','놓쳐 버린 큰 잘못','거꾸로 된 분별']);
d(25,'깨끗한 겉과 탐욕의 속','잔의 겉만 닦고 속의 탐욕을 두는 경건을 책망하세요.','cup-clean',['깨끗하게 닦은 겉','탐욕과 방종의 속','겉과 속의 차이']);
d(26,'안을 먼저 깨끗하게','내면부터 깨끗하게 해야 겉도 참으로 깨끗해짐을 가르치세요.','cup-clean',['먼저 살필 내면','탐욕을 버림','함께 깨끗해지는 겉']);
d(27,'회칠한 무덤의 대조','겉은 아름답지만 안은 죽음인 무덤으로 위선을 드러내세요.','tomb-contrast',['아름답게 보이는 겉','죽음이 있는 속','회칠한 무덤의 비유']);
d(28,'의롭게 보이는 불법','겉으로 의롭게 보이려 하면서 속은 위선과 불법으로 채우는 모순을 지적하세요.','heart',['보여 주는 의로움','속의 위선과 불법','하나님 앞의 진실']);
d(29,'꾸미는 무덤과 비석','선지자의 무덤과 의인의 비석을 꾸미는 이들의 태도를 살피세요.','tomb-contrast',['선지자의 무덤','꾸민 의인의 비석','자기를 돌아볼 질문']);
d(30,'조상의 죄에서 자신을 뺌','과거라면 선지자를 해치지 않았을 것이라고 자신하는 태도를 지적하세요.','comparison',['조상의 시대','자신을 의롭다 여김','현재의 응답']);
d(31,'현재 드러내는 같은 태도','입으로 조상과 다르다 해도 현재의 거절이 그들과 같음을 드러낸다고 하세요.','comparison',['말로 한 차별화','지금의 거절','드러난 같은 태도']);
d(32,'계속 쌓는 악에 대한 경고','조상들의 죄를 이어 채워 가는 길을 향해 엄중히 경고하세요.','warning',['조상들의 거절','이어지는 악','쌓여 가는 책임']);
d(33,'피할 수 없는 판단','악한 인도자들이 심판을 피할 수 없음을 강하게 경고하세요.','judgment',['악을 감춘 위선','드러나는 진실','피할 수 없는 판단']);
d(34,'보낸 이들까지 박해함','예수께서 보낼 사람들마저 박해하고 쫓아다닐 완고함을 예고하세요.','map',['보냄받은 사람들','박해하는 이들','마을을 따라가는 위협']);
d(35,'흘린 의로운 피의 책임','아벨부터 사가랴까지 의로운 이들을 해친 역사의 책임을 짚으세요.','lament',['의로운 이들의 피','이어진 거절의 역사','현재의 책임']);
